<?php
namespace App\Http\Controllers;
use App\Models\{Product,Purchase,PurchaseItem,Contact,Payment};use App\Services\InventoryService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class PurchaseController extends Controller
{
 public function index(){return view('purchases.index',['purchases'=>Purchase::with('items')->latest('purchased_at')->paginate(25)]);}
 public function create(){return view('purchases.create',['products'=>Product::with('baseUnit')->where('is_active',1)->get(),'suppliers'=>Contact::whereIn('type',['supplier','both'])->where('is_active',1)->get(),'businessUnits'=>\App\Models\BusinessUnit::where('is_active',1)->get()]);}
 public function store(Request $r,InventoryService $inventory){$d=$r->validate(['supplier_id'=>'nullable|exists:contacts,id','business_unit_id'=>'nullable|exists:business_units,id','paid'=>'required|numeric|min:0','notes'=>'nullable|string','items'=>'required|array|min:1','items.*.product_id'=>'required|exists:products,id','items.*.quantity'=>'required|numeric|gt:0','items.*.unit_cost'=>'required|numeric|min:0']);$purchase=DB::transaction(function()use($d,$inventory){$subtotal=collect($d['items'])->sum(fn($i)=>(float)$i['quantity']*(float)$i['unit_cost']);$paid=min((float)$d['paid'],$subtotal);$purch=Purchase::create(['purchase_no'=>'PUR-'.now()->format('ymd').'-'.Str::upper(Str::random(5)),'business_unit_id'=>$d['business_unit_id']??null,'supplier_id'=>$d['supplier_id']??null,'user_id'=>auth()->id(),'purchased_at'=>now(),'subtotal'=>$subtotal,'discount'=>0,'total'=>$subtotal,'paid'=>$paid,'due'=>$subtotal-$paid,'payment_status'=>$paid<=0?'unpaid':($paid<$subtotal?'partial':'paid'),'notes'=>$d['notes']??null]);foreach($d['items'] as $i){$product=Product::with('baseUnit')->findOrFail($i['product_id']);$qty=(float)$i['quantity'];$cost=(float)$i['unit_cost'];PurchaseItem::create(['purchase_id'=>$purch->id,'business_unit_id'=>$product->business_unit_id,'product_id'=>$product->id,'product_name'=>$product->name,'unit_name'=>$product->baseUnit->short_name,'quantity'=>$qty,'unit_cost'=>$cost,'line_total'=>$qty*$cost]);$inventory->move($product,null,$qty,'in','purchase',$purch->id,$cost,'Purchase '.$purch->purchase_no);}if($purch->supplier_id){DB::table('contact_transactions')->insert(['contact_id'=>$purch->supplier_id,'reference_type'=>'purchase','reference_id'=>$purch->id,'direction'=>'credit','amount'=>$purch->total,'description'=>'Purchase '.$purch->purchase_no,'transacted_at'=>now(),'user_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);if($paid>0)DB::table('contact_transactions')->insert(['contact_id'=>$purch->supplier_id,'reference_type'=>'purchase_payment','reference_id'=>$purch->id,'direction'=>'debit','amount'=>$paid,'description'=>'Payment made '.$purch->purchase_no,'transacted_at'=>now(),'user_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);}if($paid>0){Payment::create(['reference_type'=>'purchase','reference_id'=>$purch->id,'contact_id'=>$purch->supplier_id,'direction'=>'out','amount'=>$paid,'method'=>'cash','paid_at'=>now(),'user_id'=>auth()->id()]);DB::table('cash_transactions')->insert(['direction'=>'out','source_type'=>'purchase','source_id'=>$purch->id,'amount'=>$paid,'description'=>'Purchase '.$purch->purchase_no,'transacted_at'=>now(),'user_id'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);}return $purch;});return redirect()->route('purchases.index')->with('success','Purchase saved and stock updated.');}
}
